syntax:
struct ResourceWrapper {
    void *resource;
    void (*cleanup)(void *);
};

// Usage pattern
// Initialize
struct ResourceWrapper wrapper = { resource_pointer, cleanup_function };
// When done or on scope exit, call cleanup
wrapper.cleanup(wrapper.resource);

code_example:
typedef struct {
    int socket_fd;
} Connection;

void close_connection(void *conn_ptr) {
    Connection *conn = (Connection *)conn_ptr;
    if (conn->socket_fd >= 0) {
        close(conn->socket_fd);
        conn->socket_fd = -1;
    }
}

typedef struct {
    Connection *conn;
    void (*cleanup)(void *);
} ConnectionWrapper;

void destroy_connection(ConnectionWrapper *wrapper) {
    if (wrapper->conn) {
        wrapper->cleanup(wrapper->conn);
        free(wrapper->conn);
        wrapper->conn = NULL;
    }
}

// Usage
Connection *conn = malloc(sizeof(Connection));
conn->socket_fd = establish_connection();
ConnectionWrapper wrapper = { conn, close_connection };
// ... use connection ...
destroy_connection(&wrapper);
